    {
      "subject": "entity-c73f79cf59206d728d84",
      "statement": "The effect of Coriolis force is discussed"
    },
    {
      "subject": "entity-c73f79cf59206d728d84",
      "statement": "Results from this experiment are compared to related 1-g work, drop tower tests, aircraft experiments, and modeling"
    },
